// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address initialOwner, address newOwner) public {
        vm.assume(initialOwner != address(0));
        vm.assume(initialOwner != newOwner);

        vm.deal(initialOwner, 1 ether);

        vm.prank(address(0));
        c.transferOwnership(initialOwner);

        vm.prank(initialOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == newOwner);
    }
}
